def normalize(path):
    if not path:
        return '.'
    is_absolute = path.startswith('/')
    stack = []
    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not is_absolute:
                stack.append('..')
        else:
            stack.append(part)
    if is_absolute:
        return '/' + '/'.join(stack)
    return '/'.join(stack) if stack else '.'
```

