def strip_comments(code):
    result = []
    i = 0
    n = len(code)
    state = 0  # 0: normal, 1: single, 2: double, 3: triple single, 4: triple double, 5: comment
    while i < n:
        c = code[i]
        if state == 0:
            if c == '#':
                state = 5
            elif c == "'":
                if code[i:i+3] == "'''":
                    state = 3
                    result.append("'''")
                    i += 3
                    continue
                state = 1
                result.append("'")
            elif c == '"':
                if code[i:i+3] == '"""':
                    state = 4
                    result.append('"""')
                    i += 3
                    continue
                state = 2
                result.append('"')
            else:
                result.append(c)
        elif state == 5:
            if c == '\n':
                state = 0
                result.append('\n')
        else:
            if c == '\\':
                result.append(c)
                i += 1
                if i < n:
                    result.append(code[i])
            elif state == 1 and c == "'":
                state = 0
                result.append(c)
            elif state == 2 and c == '"':
                state = 0
                result.append(c)
            elif state == 3 and code[i:i+3] == "'''":
                state = 0
                result.append("'''")
                i += 2
            elif state == 4 and code[i:i+3] == '"""':
                state = 0
                result.append('"""')
                i += 2
            else:
                result.append(c)
        i += 1
    return ''.join(result)
```

