function debounceCount(fn, ms) {
  let timer = null;
  let args = null;
  let ctx = null;

  function call(...a) {
    args = a;
    ctx = this;
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(ctx, args);
      timer = null;
      args = null;
      ctx = null;
    }, ms);
  }

  function flush() {
    if (timer !== null) {
      clearTimeout(timer);
      fn.apply(ctx, args);
      timer = null;
      args = null;
      ctx = null;
    }
  }

  return { call, flush };
}

module.exports = debounceCount;
```

