export function debounceState(): { pending: boolean; mark(): void; clear(): void } {
  const state = { pending: false } as { pending: boolean; mark(): void; clear(): void };
  let timer: ReturnType<typeof setTimeout> | undefined = undefined;

  state.mark = function mark(): void {
    state.pending = true;
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => {
      state.pending = false;
      timer = undefined;
    }, 0);
  };

  state.clear = function clear(): void {
    state.pending = false;
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
  };

  return state;
}
