import React, { useRef, useState } from 'react';
import { View, Text, Button, StyleSheet } from 'react-native';

const MutableRefComponent = () => {
  const mutableValueRef = useRef(0);
  const [renderCount, setRenderCount] = useState(0);

  const updateRef = () => {
    mutableValueRef.current += 1;
  };

  const forceRerender = () => {
    setRenderCount(prev => prev + 1);
  };

  return (
    <View style={styles.container}>
      <Text>Ref Value: {mutableValueRef.current}</Text>
      <Text>Render Count: {renderCount}</Text>
      <Button title="Update Ref (No Re-render)" onPress={updateRef} />
      <Button title="Force Re-render" onPress={forceRerender} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
});

export default MutableRefComponent;
